//! 🧬️ SemioTableMutation — document mutation dispatch. Semantic vocabulary derived from
//! `📸️snapshot/🦀️.rs`'s `SemioTableSnapshot` shape (a name-keyed `columns` collection
//! plus an index-keyed, id-less `rows` collection whose `cells` are POSITIONALLY ALIGNED with
//! `columns`) per `../SEMANTIC-MUTATIONS-OVERHAUL/📓️taxonomy.md`/`📓️derivation-rules.md`. `impl
//! protocol::Mutation`/`SemanticMutation` below are generated by `#[derive(dsl::Mutations)]` —
//! never hand-written.
//!
//! `columns: Vec<SemioTableColumn>` is name-keyed (`📓️taxonomy.md` addressing rule #2 — like cad
//! layers/xlsx sheets): `create-column`/`delete-column`/`rename-column`/`reorder-columns` address
//! by `name`. `rows: Vec<SemioTableRow>` has no stable id (addressing rule #3): `insert-row`/
//! `remove-row` address by index (inserted = FINAL-state, removed = BASE-state), `reorder-rows`
//! moves one row within the sequence, `edit-cell` replaces one cell's authored value addressed by
//! `{row_index, column_name}`. Every column insert/remove/reorder applies the IDENTICAL
//! insert/remove/reorder, at the IDENTICAL index, to every row's `cells` — the CRITICAL alignment
//! invariant documented on `SemioTableSnapshot` itself.
//!
//! Every triad leaf is mounted directly as a `mutations`-sibling module in `🦀️.rs` (the stdio
//! W2 agent owns `🦀️.rs`, so no self-wiring `#[path = "."]` blocks are needed here).

use crate::artifacts::semio::standards::v1::subsets::table::schema::diff::SemioTableDiff;
use crate::artifacts::semio::standards::v1::subsets::table::schema::snapshot::SemioTableSnapshot;

//#region 🔖️Leaves
use super::create_column;
use super::delete_column;
use super::edit_cell;
use super::insert_row;
use super::remove_row;
use super::rename_column;
use super::reorder_columns;
use super::reorder_rows;
//#endregion 🔖️Leaves

//#region 🔖️Mutations
/// 🧬️ Every variant wraps exactly one `protocol::MutationKind<SemioTableSnapshot,
/// SemioTableMutation>` payload struct declared in the corresponding triad leaf's
/// `🦠️mutation/🦀️.rs`. This plugin crate reaches the derive through the `dsl` extern-crate
/// alias `🦀️.rs` declares (`extern crate semio_framework_os_kernel as dsl;`), the same spelling
/// `✳️text`'s already-compiling facet uses.
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, dsl::Mutations)]
#[mutations(snapshot = SemioTableSnapshot, diff = SemioTableDiff, schema = "s.stdio.semio.table")]
pub enum SemioTableMutation {
    CreateColumn(create_column::CreateColumn),
    DeleteColumn(delete_column::DeleteColumn),
    RenameColumn(rename_column::RenameColumn),
    ReorderColumns(reorder_columns::ReorderColumns),
    InsertRow(insert_row::InsertRow),
    RemoveRow(remove_row::RemoveRow),
    ReorderRows(reorder_rows::ReorderRows),
    EditCell(edit_cell::EditCell),
}

/// 🏷️ Kebab-case spelling of every `SemioTableMutation` variant, in declaration order — the
/// vocabulary the `semio-v1-table` mutation catalog (`../../🔣️oracle.json`) declares and
/// `mutate-semio-table`'s exhaustive test case measures itself against. `kinds_match_the_enum_and_
/// the_catalog` below is what keeps this list honest against the enum, since the framework never
/// parses Rust.
pub const KINDS: &[&str] = &["create-column", "delete-column", "rename-column", "reorder-columns", "insert-row", "remove-row", "reorder-rows", "edit-cell"];
//#endregion 🔖️Mutations

//#region 🔖️Apply
/// ▶️ Applies a mutation to `snapshot` in place, returning the diff — kept from the pre-wave facet
/// (consumed by `../🦀️.rs`'s `SemioTableBuilderConstruction::mutate`).
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn apply_semio_table_mutation(snapshot: &mut SemioTableSnapshot, mutation: &SemioTableMutation) -> protocol::MutationOutcome<SemioTableDiff> {
    use protocol::Mutation;
    let outcome = <SemioTableMutation as Mutation<SemioTableSnapshot>>::diff(mutation, snapshot);
    outcome.apply_to(snapshot)
}

/// ↩️ Computes `mutation`'s own inverse against `base` — a thin wrapper around
/// `protocol::Mutation::inverse` so external Rust callers that cannot name this crate's private
/// `protocol` extern-crate item (the `mutate-semio-table` test adapter, whose `inverse-<kind>` scenarios
/// need a mutation's own computed inverse) can still reach the inverse law that
/// [`apply_semio_table_mutation`] alone cannot. Same shape as `✳️kit`'s `inverse_semio_kit_mutation`.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn inverse_semio_table_mutation(mutation: &SemioTableMutation, base: &SemioTableSnapshot) -> Vec<SemioTableMutation> {
    use protocol::Mutation;
    <SemioTableMutation as Mutation<SemioTableSnapshot>>::inverse(mutation, base)
}

/// 📥️ Decodes this facet's own externally-tagged (`{"<VariantName>": {<snake_case payload>}}`)
/// JSON projection — no `#[value(rename_all)]` sits on this enum or its payload structs, which is
/// exactly the shape the committed `<kind>/🧪️tests/<fixture>/🦠️mutation/🔣️.json` vectors
/// carry — into a real [`SemioTableMutation`]. `reorder-columns`/`reorder-rows` address positions (`to_index`) while the rename/edit kinds
/// address names — decoding keeps those two addressing modes exactly as the vector states them.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn decode_semio_table_mutation_json(text: &str) -> Result<SemioTableMutation, String> {
    pack::from_json_str(text).map_err(|error| error.to_string())
}
//#endregion 🔖️Apply

//#region 🧪️Tests
#[cfg(test)]
mod tests {
    use super::*;
    use crate::artifacts::semio::standards::v1::subsets::table::schema::snapshot::{SemioTableCellKind, SemioTableColumn, SemioTableRow, STDIO_SEMIOTABLE_DOCUMENT_SCHEMA};
    use crate::artifacts::semio::standards::v1::subsets::value::schema::snapshot::SemioValue;
    use protocol::{Mutation, MutationDiff, SemanticMutation};

    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn fixture() -> SemioTableSnapshot {
        SemioTableSnapshot {
            schema: STDIO_SEMIOTABLE_DOCUMENT_SCHEMA.into(),
            columns: vec![SemioTableColumn { name: "label".into(), kind: SemioTableCellKind::Str }, SemioTableColumn { name: "score".into(), kind: SemioTableCellKind::Float }],
            rows: vec![
                SemioTableRow { cells: vec![SemioValue::Str { value: "a".into() }, SemioValue::Float { lexeme: "1.000".into() }] },
                SemioTableRow { cells: vec![SemioValue::Str { value: "b".into() }, SemioValue::Float { lexeme: "2.000".into() }] },
            ],
        }
    }

    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn round_trip(base: &SemioTableSnapshot, operation: &SemioTableMutation) -> SemioTableSnapshot {
        let forward = operation.diff(base).diff().apply(base).expect("apply must succeed for a well-formed fixture");
        let backwards = operation.inverse(base);
        let mut restored = forward.clone();
        // 🔧️ Each inverse's diff must be computed against the CURRENT (`restored`) state, not the
        // stale pre-operation `base` — a whole-list-replace diff shape reconstructs the entire
        // collection from whatever base it is given, so diffing against the wrong base silently
        // discards the forward mutation's effect instead of undoing it (see `✳️text`'s own fix).
        for back in &backwards {
            restored = back.diff(&restored).diff().apply(&restored).expect("apply must succeed for a well-formed fixture");
        }
        assert_eq!(&restored, base, "inverse must exactly restore the pre-operation fixture");
        forward
    }

    /// 🧪️ CRITICAL alignment invariant: creating a column inserts a `Null` cell at the same index
    /// into EVERY row.
    #[semio_framework_async_macros::async_test]
    async fn create_column_keeps_rows_aligned() {
        let base = fixture();
        let create = SemioTableMutation::CreateColumn(create_column::CreateColumn { name: "notes".into(), kind: SemioTableCellKind::Str, index: Some(1) });
        let after = round_trip(&base, &create);
        assert_eq!(after.columns.len(), base.columns.len() + 1);
        assert_eq!(after.columns[1].name, "notes");
        for (row, base_row) in after.rows.iter().zip(&base.rows) {
            assert_eq!(row.cells.len(), after.columns.len());
            assert_eq!(row.cells[1], SemioValue::Null);
            assert_eq!(row.cells[0], base_row.cells[0]);
            assert_eq!(row.cells[2], base_row.cells[1]);
        }
    }

    /// 🧪️ CRITICAL alignment invariant: deleting a column removes the aligned cell from EVERY
    /// row, and the cascade-capturing inverse restores the exact original per-row cell values (not
    /// just `Null`).
    #[semio_framework_async_macros::async_test]
    async fn delete_column_captures_full_row_cascade_for_inverse() {
        let base = fixture();
        let delete = SemioTableMutation::DeleteColumn(delete_column::DeleteColumn { name: "label".into() });
        let after = round_trip(&base, &delete);
        assert_eq!(after.columns.len(), 1);
        assert_eq!(after.columns[0].name, "score");
        for row in &after.rows {
            assert_eq!(row.cells.len(), 1);
        }

        let undo = delete.inverse(&base);
        assert_eq!(undo.len(), 1 + base.rows.len(), "expected one CreateColumn plus one EditCell per row");
        assert!(matches!(&undo[0], SemioTableMutation::CreateColumn(_)));
        for m in &undo[1..] {
            assert!(matches!(m, SemioTableMutation::EditCell(_)));
        }
    }

    #[semio_framework_async_macros::async_test]
    async fn delete_column_of_an_absent_name_has_an_empty_inverse() {
        let base = fixture();
        let delete = SemioTableMutation::DeleteColumn(delete_column::DeleteColumn { name: "missing".into() });
        assert!(delete.inverse(&base).is_empty());
        assert_eq!(delete.diff(&base).diff().apply(&base).expect("apply must succeed for a well-formed fixture"), base, "an absent-name delete is a no-op");
    }

    #[semio_framework_async_macros::async_test]
    async fn rename_column_round_trips() {
        let base = fixture();
        let rename = SemioTableMutation::RenameColumn(rename_column::RenameColumn { name: "label".into(), new_name: "title".into() });
        let after = round_trip(&base, &rename);
        assert_eq!(after.columns[0].name, "title");
        assert_eq!(after.rows, base.rows, "rename must not touch rows");
    }

    /// 🧪️ CRITICAL alignment invariant: reordering a column applies the identical remove-then-
    /// insert to every row's cells.
    #[semio_framework_async_macros::async_test]
    async fn reorder_columns_keeps_rows_aligned() {
        let base = fixture();
        let reorder = SemioTableMutation::ReorderColumns(reorder_columns::ReorderColumns { name: "score".into(), to_index: 0 });
        let after = round_trip(&base, &reorder);
        assert_eq!(after.columns[0].name, "score");
        assert_eq!(after.columns[1].name, "label");
        for (row, base_row) in after.rows.iter().zip(&base.rows) {
            assert_eq!(row.cells[0], base_row.cells[1]);
            assert_eq!(row.cells[1], base_row.cells[0]);
        }
    }

    #[semio_framework_async_macros::async_test]
    async fn insert_remove_row_round_trips() {
        let base = fixture();
        let new_row = SemioTableRow { cells: vec![SemioValue::Str { value: "c".into() }, SemioValue::Float { lexeme: "3.000".into() }] };

        let insert = SemioTableMutation::InsertRow(insert_row::InsertRow { index: 1, row: new_row.clone() });
        let after_insert = round_trip(&base, &insert);
        assert_eq!(after_insert.rows.len(), base.rows.len() + 1);
        assert_eq!(after_insert.rows[1], new_row);

        let undo = insert.inverse(&base);
        assert_eq!(undo, vec![SemioTableMutation::RemoveRow(remove_row::RemoveRow { index: 1 })]);

        let remove = SemioTableMutation::RemoveRow(remove_row::RemoveRow { index: 0 });
        let after_remove = round_trip(&base, &remove);
        assert_eq!(after_remove.rows.len(), base.rows.len() - 1);
        assert_eq!(after_remove.rows[0], base.rows[1]);
    }

    #[semio_framework_async_macros::async_test]
    async fn remove_row_of_an_out_of_range_index_has_an_empty_inverse() {
        let base = fixture();
        let remove = SemioTableMutation::RemoveRow(remove_row::RemoveRow { index: 99 });
        assert!(remove.inverse(&base).is_empty(), "removing an absent index has nothing to undo");
        assert_eq!(remove.diff(&base).diff().apply(&base).expect("apply must succeed for a well-formed fixture"), base, "an out-of-range remove is a no-op");
    }

    #[semio_framework_async_macros::async_test]
    async fn reorder_rows_round_trips() {
        let base = fixture();
        let reorder = SemioTableMutation::ReorderRows(reorder_rows::ReorderRows { from: 0, to: 1 });
        let after = round_trip(&base, &reorder);
        assert_eq!(after.rows[0], base.rows[1]);
        assert_eq!(after.rows[1], base.rows[0]);
    }

    #[semio_framework_async_macros::async_test]
    async fn edit_cell_round_trips() {
        let base = fixture();
        let edit = SemioTableMutation::EditCell(edit_cell::EditCell { row_index: 0, column_name: "score".into(), new_value: SemioValue::Float { lexeme: "9.000".into() } });
        let after = round_trip(&base, &edit);
        assert_eq!(after.rows[0].cells[1], SemioValue::Float { lexeme: "9.000".into() });
        assert_eq!(after.columns, base.columns, "edit-cell must not touch columns");

        let missing = SemioTableMutation::EditCell(edit_cell::EditCell { row_index: 99, column_name: "score".into(), new_value: SemioValue::Null });
        assert!(missing.inverse(&base).is_empty(), "editing an absent row has nothing to undo");
    }

    #[semio_framework_async_macros::async_test]
    async fn semantic_kinds_cover_every_variant() {
        assert_eq!(SemioTableMutation::kinds().len(), 8);
        let mutation = SemioTableMutation::RemoveRow(remove_row::RemoveRow { index: 2 });
        assert_eq!(mutation.semantics().kind, "remove-row");
        assert_eq!(mutation.semantics().record, "RemovedRow");
        assert_eq!(mutation.target(), vec!["2".to_string()]);
    }

    /// 🏷️ `KINDS` (this facet's own const, consumed by `mutate-semio-table`'s adapter) must name
    /// every declared variant, in the exact order and spelling `#[derive(dsl::Mutations)]` assigns —
    /// the framework never parses Rust, so this is what keeps the catalog honest.
    #[semio_framework_async_macros::async_test]
    async fn kinds_match_the_enum_and_the_catalog() {
        let descriptors = SemioTableMutation::kinds();
        assert_eq!(KINDS.len(), descriptors.len(), "KINDS must name exactly one entry per declared variant");
        for (kind, descriptor) in KINDS.iter().zip(descriptors.iter()) {
            assert_eq!(*kind, descriptor.kind, "KINDS must match #[derive(dsl::Mutations)]'s own declaration order and spelling");
        }
        let manifest = include_str!("../../🧪️oracle/🔣️.json");
        for kind in KINDS {
            assert!(manifest.contains(&format!("\"{kind}\"")), "KINDS entry {kind:?} must also appear in the committed oracle manifest's catalog");
        }
    }
}
//#endregion 🧪️Tests

